+            path = "tox.schema.json"
+            include = ["pyproject.toml"]
+        """)
+        content = dedent("""\
+            [tool.tox]
+            requires = ['tox>=4']
+            env_list = ['py']
+            skip_missing_interpreters = true
+
+            [tool.tox.env_run_base]
+            commands = [['pytest']]
